fn sum(a: &Vec<u32>, b: &Vec<u32>) -> Vec<u32> {
    debug_assert!(a.len() == b.len(), "Input vectors must have the same length");
    a.iter()
     .zip(b.iter())
     .map(|(x, y)| x + y)
     .collect()
}